css:
    :root {
      --bg-dark: #08080c;
      --bg-surface: #0e1017;
      --bg-card: rgba(18, 20, 30, 0.72);
      --bg-card-hover: rgba(26, 30, 44, 0.85);
      --border-glass: rgba(255, 255, 255, 0.08);
      --border-focus: rgba(99, 102, 241, 0.6);
      --accent-primary: #6366f1;
      --accent-gradient: linear-gradient(135deg, #6366f1 0%, #3b82f6 50%, #06b6d4 100%);
      --accent-glow: rgba(99, 102, 241, 0.35);
      --emerald: #10b981;
      --amber: #f59e0b;
      --rose: #f43f5e;
      --text-white: #ffffff;
      --text-silver: #94a3b8;
      --text-muted: #64748b;
      --font-main: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
      --font-mono: 'Space Grotesk', monospace;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      background-color: var(--bg-dark);
      background-image: 
        radial-gradient(circle at 10% 20%, rgba(99, 102, 241, 0.08) 0%, transparent 40%),
        radial-gradient(circle at 90% 80%, rgba(59, 130, 246, 0.07) 0%, transparent 45%),
        radial-gradient(circle at 50% 50%, rgba(6, 182, 212, 0.04) 0%, transparent 60%);
      color: var(--text-white);
      font-family: var(--font-main);
      min-height: 100vh;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }

    ::-webkit-scrollbar { width: 7px; height: 7px; }
    ::-webkit-scrollbar-track { background: rgba(0, 0, 0, 0.4); }
    ::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.15); border-radius: 4px; }
    ::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, 0.28); }

    /* VIEW 1: FROSTED GLASS LUXURY LOGIN SCREEN WITH ROTATING BACKGROUNDS (MAIN STOREFRONT THEME: #151413 / #EBEBEB / #FFFFFF) */
    #auth-view {
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 84px 20px 44px 20px;
      position: relative;
      overflow: hidden;
      background: #151413;
    }

    .auth-bg-slideshow {
      position: absolute;
      inset: 0;
      z-index: 0;
      overflow: hidden;
    }
    .auth-bg-slide {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
      opacity: 0;
      transform: scale(1.03);
      transition: opacity 1.3s ease-in-out, transform 6s ease-out;
    }
    .auth-bg-slide.active {
      opacity: 1;
      transform: scale(1);
    }
    .auth-bg-scrim {
      position: absolute;
      inset: 0;
      z-index: 1;
      background: radial-gradient(circle at center, rgba(21, 20, 19, 0.22) 0%, rgba(21, 20, 19, 0.56) 100%);
      pointer-events: none;
    }

    .auth-top-bar {
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      z-index: 3;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 24px 40px;
    }
    .auth-top-brand {
      display: flex;
      align-items: center;
      gap: 12px;
      text-decoration: none;
    }
    .auth-top-brand-mark {
      width: 34px;
      height: 34px;
      border-radius: 50%;
      background: #151413;
      border: 1px solid rgba(255, 255, 255, 0.24);
      display: flex;
      align-items: center;
      justify-content: center;
      color: #ffffff;
      font-weight: 800;
      font-size: 15px;
      font-family: var(--font-main);
      box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
    }
    .auth-top-brand-name {
      font-family: var(--font-main);
      font-size: 18px;
      font-weight: 800;
      letter-spacing: 3px;
      color: #ffffff;
      text-shadow: 0 2px 10px rgba(0, 0, 0, 0.45);
    }
    .auth-top-brand-sub {
      font-size: 9px;
      letter-spacing: 1.8px;
      text-transform: uppercase;
      color: rgba(255, 255, 255, 0.8);
      text-shadow: 0 1px 6px rgba(0, 0, 0, 0.5);
    }

    .back-to-store-pill {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 9px 18px;
      background: #151413;
      border: 1px solid rgba(255, 255, 255, 0.18);
      border-radius: 999px;
      color: #ffffff;
      text-decoration: none;
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.4px;
      transition: all 0.25s ease;
      box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
    }
    .back-to-store-pill:hover {
      background: #ffffff;
      color: #151413;
      transform: translateX(-2px);
    }

    /* Centered Frosted Glass Login Card */
    .auth-container {
      width: 100%;
      max-width: 430px;
      position: relative;
      z-index: 3;
    }

    .auth-card-pane {
      background: rgba(240, 239, 236, 0.84);
      border: 1px solid rgba(255, 255, 255, 0.86);
      backdrop-filter: blur(24px);
      -webkit-backdrop-filter: blur(24px);
      border-radius: 26px;
      padding: 36px 34px 30px 34px;
      box-shadow: 0 28px 70px rgba(0, 0, 0, 0.36);
      position: relative;
      color: #151413;
      text-align: center;
    }
    .auth-card-emblem {
      width: 42px;
      height: 42px;
      margin: 0 auto 12px auto;
      border-radius: 50%;
      background: #151413;
      border: 1px solid rgba(21, 20, 19, 0.12);
      display: flex;
      align-items: center;
      justify-content: center;
      color: #ffffff;
      font-size: 17px;
      box-shadow: 0 4px 14px rgba(21, 20, 19, 0.2);
    }
    .auth-card-title {
      font-family: var(--font-main);
      font-size: 32px;
      font-weight: 800;
      color: #151413;
      letter-spacing: -0.6px;
      margin-bottom: 6px;
      line-height: 1.1;
    }
    .auth-card-sub {
      font-size: 13px;
      color: #66625c;
      margin-bottom: 20px;
    }

    .role-pills-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 7px;
      margin-bottom: 18px;
    }
    .role-pill-btn {
      padding: 8px 6px;
      background: rgba(255, 255, 255, 0.72);
      border: 1px solid rgba(21, 20, 19, 0.12);
      border-radius: 10px;
      color: #66625c;
      font-size: 11px;
      font-weight: 700;
      cursor: pointer;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 3px;
      transition: all 0.2s ease;
      font-family: inherit;
    }
    .role-pill-btn span.role-icon { font-size: 14px; }
    .role-pill-btn:hover {
      background: #ffffff;
      border-color: #151413;
      color: #151413;
    }
    .role-pill-btn.active {
      background: #151413;
      border-color: #151413;
      color: #ffffff;
      box-shadow: 0 6px 16px rgba(21, 20, 19, 0.22);
    }

    /* Keep modal .auth-form-group / .auth-input rules intact for #product-modal, and style #auth-view cleanly */
    .auth-form-group { margin-bottom: 14px; text-align: left; }
    .auth-form-label { display: block; font-size: 12px; font-weight: 600; color: var(--text-silver); margin-bottom: 6px; }
    .auth-input-wrap { position: relative; display: flex; align-items: center; }
    .auth-input-wrap .input-icon { position: absolute; left: 15px; color: #66625c; font-size: 14px; pointer-events: none; }
    .auth-input {
      width: 100%; height: 46px; padding: 0 16px 0 42px;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid var(--border-glass);
      border-radius: 12px;
      color: #fff; font-size: 13.5px; font-family: inherit; outline: none;
      transition: border-color 0.2s, background 0.2s, box-shadow 0.2s;
    }
    #auth-view .auth-input {
      background: rgba(255, 255, 255, 0.92);
      border: 1px solid rgba(21, 20, 19, 0.14);
      color: #151413;
    }
    #auth-view .auth-input::placeholder { color: #777777; }
    #auth-view .auth-input:focus {
      background: #ffffff;
      border-color: #151413;
      box-shadow: 0 0 0 3px rgba(21, 20, 19, 0.1);
    }
    .pwd-toggle-btn {
      position: absolute; right: 12px; background: none; border: none;
      color: #66625c; cursor: pointer; font-size: 15px; padding: 6px;
    }
    .pwd-toggle-btn:hover { color: #151413; }

    .auth-options-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-size: 12px;
      color: #66625c;
      margin: 4px 2px 16px 2px;
    }
    .auth-options-row label { display: inline-flex; align-items: center; gap: 6px; cursor: pointer; }
    .auth-options-row input[type="checkbox"] { accent-color: #151413; }
    .auth-options-row a { color: #151413; font-weight: 700; text-decoration: none; }
    .auth-options-row a:hover { text-decoration: underline; }

    .auth-submit-btn {
      width: 100%; height: 48px;
      background: #151413;
      color: #ffffff;
      border: none; border-radius: 999px; font-size: 14px; font-weight: 700; letter-spacing: 0.4px;
      cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 8px;
      box-shadow: 0 8px 22px rgba(21, 20, 19, 0.28);
      transition: all 0.25s ease;
    }
    .auth-submit-btn:hover {
      background: #000000;
      transform: translateY(-1px);
      box-shadow: 0 12px 26px rgba(21, 20, 19, 0.36);
    }

    .auth-or-divider {
      display: flex; align-items: center; gap: 12px; margin: 18px 0 14px 0;
      font-size: 11px; font-weight: 700; color: #66625c; letter-spacing: 0.8px;
    }
    .auth-or-divider::before, .auth-or-divider::after {
      content: ''; flex: 1; height: 1px; background: rgba(21, 20, 19, 0.15);
    }

    .quick-preset-btns { display: flex; gap: 8px; }
    .quick-preset-btn {
      flex: 1; padding: 9px 6px;
      background: rgba(255, 255, 255, 0.88);
      border: 1px solid rgba(21, 20, 19, 0.14); border-radius: 999px;
      color: #151413; font-size: 11px; font-weight: 700; cursor: pointer; font-family: inherit;
      transition: all 0.2s;
    }
    .quick-preset-btn:hover {
      background: #151413;
      border-color: #151413;
      color: #ffffff;
    }

    .auth-slide-dots {
      position: relative;
      z-index: 3;
      display: flex;
      gap: 8px;
      margin-top: 18px;
    }
    .auth-slide-dot {
      width: 9px; height: 9px; border-radius: 999px; border: none;
      background: rgba(255, 255, 255, 0.45); cursor: pointer; transition: all 0.3s;
    }
    .auth-slide-dot.active {
      width: 24px;
      background: #ffffff;
      box-shadow: 0 0 10px rgba(0, 0, 0, 0.25);
    }

    @media (max-width: 560px) {
      .auth-top-bar { padding: 16px 20px; }
      .auth-card-pane { padding: 28px 22px; }
    }

    body.dash-mode {
      height: 100vh;
      max-height: 100vh;
      overflow: hidden;
    }

    /* VIEW 2: MASTER ADMIN DASHBOARD (SHERAH LIGHT SAAS UI) */
    #dashboard-view {
      display: none;
      height: 100vh;
      max-height: 100vh;
      overflow: hidden;
      flex-direction: column;
      background: #f5f7fb;
      color: #0f172a;
    }

    /* Top Header Bar */
    .dash-top-bar {
      height: 70px;
      background: #ffffff;
      border-bottom: 1px solid #eef2f6;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 28px;
      position: sticky;
      top: 0;
      z-index: 100;
      flex-shrink: 0;
    }
    .quantro-search-capsule {
      display: flex;
      align-items: center;
      gap: 10px;
      background: #f5f7fb;
      border: 1px solid #e2e8f0;
      border-radius: 10px;
      padding: 8px 14px;
      width: 340px;
      transition: all 0.2s ease;
    }
    .quantro-search-capsule:focus-within {
      border-color: #6176fe;
      background: #ffffff;
      box-shadow: 0 0 0 3px rgba(97, 118, 254, 0.12);
    }
    .quantro-search-capsule input {
      background: none;
      border: none;
      outline: none;
      color: #0f172a;
      font-size: 13px;
      width: 100%;
      font-family: inherit;
    }
    .quantro-search-capsule input::placeholder { color: #94a3b8; }
    .search-filter-icon {
      background: none;
      border: none;
      color: #64748b;
      font-size: 15px;
      cursor: pointer;
      display: flex;
      align-items: center;
    }

    .topbar-right-controls {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .quantro-pill-btn-dark {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 7px 14px;
      background: #f8fafc;
      border: 1px solid #e2e8f0;
      border-radius: 999px;
      color: #334155;
      font-size: 12px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.2s;
    }
    .quantro-pill-btn-dark:hover { background: #eff6ff; border-color: #cbd5e1; }
    .quantro-icon-btn {
      width: 38px;
      height: 38px;
      border-radius: 10px;
      background: #f8fafc;
      border: 1px solid #eef2f6;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #475569;
      cursor: pointer;
      position: relative;
      transition: all 0.2s;
    }
    .quantro-icon-btn:hover { background: #eff6ff; color: #4f46e5; }
    .notif-dot {
      position: absolute;
      top: 7px;
      right: 7px;
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #6176fe;
    }
    .quantro-user-widget {
      display: flex;
      align-items: center;
      gap: 10px;
      cursor: pointer;
      padding: 4px 12px 4px 6px;
      border-radius: 999px;
      background: #f8fafc;
      border: 1px solid #e2e8f0;
      transition: background 0.2s;
    }
    .quantro-user-widget:hover { background: #eff6ff; }
    .quantro-user-img {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: linear-gradient(135deg, #6176fe, #4f46e5);
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 800;
      color: #fff;
      font-size: 12px;
    }
    .quantro-user-name { font-size: 12.5px; font-weight: 700; color: #0f172a; line-height: 1.2; }
    .quantro-user-role { font-size: 10.5px; color: #64748b; font-weight: 600; text-transform: capitalize; }

    .dash-main-container {
      display: flex;
      flex: 1;
      min-height: 0;
      height: calc(100vh - 70px);
      overflow: hidden;
      background: #f5f7fb;
    }

    /* Clean White Sidebar */
    .dash-sidebar {
      width: 235px;
      background: #ffffff;
      border-right: 1px solid #eef2f6;
      padding: 20px 14px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 16px;
      flex-shrink: 0;
      height: 100%;
      overflow-y: auto;
      scrollbar-width: thin;
      scrollbar-color: #cbd5e1 transparent;
    }
    .quantro-brand-header {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 4px 10px 18px 10px;
      border-bottom: 1px solid #f1f5f9;
      margin-bottom: 10px;
    }
    .quantro-logo-mark {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      background: linear-gradient(135deg, #6176fe, #38bdf8);
      display: flex;
      align-items: center;
      justify-content: center;
      color: #fff;
      font-weight: 900;
      font-size: 16px;
    }
    .quantro-brand-title { font-size: 19px; font-weight: 900; letter-spacing: 0.5px; color: #0f172a; }
    .sidebar-nav-list { display: flex; flex-direction: column; gap: 4px; list-style: none; }
    .nav-item-btn {
      width: 100%;
      display: flex;
      align-items: center;
      gap: 11px;
      padding: 10px 12px;
      background: none;
      border: 1px solid transparent;
      border-radius: 10px;
      color: #64748b;
      font-size: 13.5px;
      font-weight: 600;
      cursor: pointer;
      font-family: inherit;
      text-align: left;
      transition: all 0.2s ease;
    }
    .nav-item-btn:hover { background: #f8fafc; color: #0f172a; }
    .nav-item-btn.active { background: #eff4ff; color: #4f46e5; font-weight: 700; }
    .nav-item-btn .nav-icon { font-size: 16px; width: 20px; text-align: center; }
    .nav-item-btn .nav-count-badge {
      margin-left: auto;
      padding: 2px 8px;
      background: #f1f5f9;
      border-radius: 999px;
      font-size: 11px;
      font-weight: 700;
      color: #475569;
    }
    .nav-item-btn.active .nav-count-badge { background: #6176fe; color: #ffffff; }

    .sidebar-promo-card {
      background: #f8fafc;
      border: 1px solid #e2e8f0;
      border-radius: 14px;
      padding: 16px 14px;
      display: flex;
      flex-direction: column;
      gap: 6px;
      margin-top: auto;
    }
    .promo-crown-icon { width: 30px; height: 30px; border-radius: 8px; background: #eff4ff; display: flex; align-items: center; justify-content: center; font-size: 15px; }
    .promo-title { font-size: 13px; font-weight: 800; color: #0f172a; }
    .promo-desc { font-size: 11px; color: #64748b; line-height: 1.4; }
    .promo-btn {
      margin-top: 4px; padding: 8px 12px; background: #6176fe; border: none; border-radius: 8px;
      color: #ffffff; font-size: 12px; font-weight: 700; cursor: pointer; transition: all 0.2s; text-align: center;
    }
    .promo-btn:hover { background: #4f46e5; }

    .dash-content-area {
      flex: 1;
      padding: 24px 28px 40px 28px;
      overflow-y: auto;
      max-width: 1480px;
      min-height: 0;
      height: 100%;
      background: #f5f7fb;
    }

    /* SHERAH DASHBOARD OVERVIEW CANVAS */
    .quantro-white-canvas {
      display: flex;
      flex-direction: column;
      gap: 20px;
      margin-bottom: 24px;
      color: #0f172a;
    }
    .canvas-header-row { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; }
    .canvas-title { font-size: 22px; font-weight: 800; letter-spacing: -0.4px; color: #0f172a; }
    .canvas-sub { font-size: 13px; color: #64748b; margin-top: 2px; }
    .btn-create-report {
      display: inline-flex; align-items: center; gap: 6px; padding: 9px 16px;
      background: #6176fe; color: #ffffff; border: none; border-radius: 8px;
      font-size: 12.5px; font-weight: 700; cursor: pointer; transition: all 0.2s;
    }
    .btn-create-report:hover { background: #4f46e5; transform: translateY(-1px); }

    /* 4 Top KPI Metric Cards (Sherah Style with Top Circular Icon) */
    .metrics-grid-4 {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 18px;
      margin-top: 10px;
    }
    .sherah-kpi-card {
      background: #ffffff;
      border: 1px solid #eef2f6;
      border-radius: 14px;
      padding: 22px 20px 18px 20px;
      position: relative;
      box-shadow: 0 2px 10px rgba(15, 23, 42, 0.03);
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    .sherah-kpi-icon {
      position: absolute;
      top: -14px;
      right: 20px;
      width: 42px;
      height: 42px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      box-shadow: 0 4px 10px rgba(15, 23, 42, 0.06);
      border: 3px solid #ffffff;
    }
    .sherah-kpi-top { display: flex; justify-content: space-between; align-items: flex-start; padding-top: 4px; }
    .sherah-kpi-label { font-size: 13px; font-weight: 600; color: #64748b; }
    .sherah-kpi-value { font-size: 24px; font-weight: 800; color: #0f172a; margin-top: 4px; font-family: var(--font-mono); }
    .sherah-kpi-right { text-align: right; padding-top: 18px; }
    .sherah-kpi-growth { font-size: 12px; font-weight: 700; display: block; }
    .sherah-kpi-link {
      font-size: 11.5px; color: #64748b; text-decoration: underline; cursor: pointer;
      background: none; border: none; font-family: inherit; padding: 0; margin-top: 4px;
    }
    .sherah-kpi-link:hover { color: #4f46e5; }

    /* Charts Asymmetric Row */
    .sherah-mid-grid {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 18px;
    }
    .sherah-left-col { display: flex; flex-direction: column; gap: 18px; }
    .sherah-card {
      background: #ffffff;
      border: 1px solid #eef2f6;
      border-radius: 14px;
      padding: 20px 22px;
      box-shadow: 0 2px 10px rgba(15, 23, 42, 0.03);
      display: flex;
      flex-direction: column;
    }
    .sherah-card-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 16px;
      flex-wrap: wrap;
      gap: 10px;
    }
    .sherah-card-title { font-size: 16px; font-weight: 800; color: #0f172a; }
    .sherah-pill-tabs { display: flex; gap: 6px; }
    .sherah-pill-tab {
      padding: 5px 12px; border-radius: 6px; border: 1px solid #e2e8f0; background: #ffffff;
      color: #64748b; font-size: 11.5px; font-weight: 700; cursor: pointer; transition: all 0.15s;
    }
    .sherah-pill-tab.active { background: #facc15; border-color: #facc15; color: #0f172a; }

    /* Dual Ring Mini Cards */
    .sherah-rings-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
    .sherah-ring-card {
      background: #ffffff;
      border: 1px solid #eef2f6;
      border-radius: 14px;
      padding: 18px 20px;
      box-shadow: 0 2px 10px rgba(15, 23, 42, 0.03);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }
    .sherah-ring-left { display: flex; flex-direction: column; gap: 6px; }
    .sherah-ring-label { font-size: 12.5px; font-weight: 600; color: #64748b; }
    .sherah-ring-val { font-size: 18px; font-weight: 800; color: #0f172a; font-family: var(--font-mono); }

    /* Monthly Stats Legend */
    .sherah-stats-legend { display: flex; gap: 22px; margin-bottom: 14px; flex-wrap: wrap; }
    .sherah-legend-block { display: flex; flex-direction: column; gap: 2px; }
    .sherah-legend-top { display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; color: #64748b; }
    .sherah-legend-num { font-size: 15px; font-weight: 800; color: #0f172a; padding-left: 14px; font-family: var(--font-mono); }
    .legend-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; flex-shrink: 0; }

    /* Bottom Charts Row (Revenue + World Map) */
    .sherah-bottom-charts {
      display: grid;
      grid-template-columns: 1.25fr 0.75fr;
      gap: 18px;
    }
    .world-map-svg-wrap { position: relative; width: 100%; height: 220px; display: flex; align-items: center; justify-content: center; }
    .map-pulse-beacon {
