    }
    @keyframes mapPulse {
      0% { box-shadow: 0 0 0 0 rgba(97, 118, 254, 0.55); }
      70% { box-shadow: 0 0 0 12px rgba(97, 118, 254, 0); }
      100% { box-shadow: 0 0 0 0 rgba(97, 118, 254, 0); }
