    /* Top Products 4-Card Showcase */
    .sherah-top-products-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }
    .sherah-prod-card {
      border: 1px solid #eef2f6;
      border-radius: 12px;
      padding: 14px;
      background: #ffffff;
      transition: all 0.2s ease;
      display: flex;
      flex-direction: column;
      gap: 10px;
