    .sherah-prod-title { font-size: 13px; font-weight: 700; color: #0f172a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .sherah-prod-price-row { display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 800; color: #0f172a; }
    .sherah-prod-meta { display: flex; align-items: center; justify-content: space-between; font-size: 11.5px; color: #64748b; }

    /* Sub-Views Light Theme (Products, Discounts, Orders) */
    .content-header-banner { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 22px; flex-wrap: wrap; gap: 14px; }
    .page-main-heading { font-size: 24px; font-weight: 800; letter-spacing: -0.5px; color: #0f172a; margin-bottom: 4px; }
    .page-sub-heading { font-size: 13px; color: #64748b; }

    .stats-cards-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 24px; }
    .stat-card-glass {
