    }
    .stat-card-glass:hover { transform: translateY(-2px); border-color: #cbd5e1; }
    .stat-top-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
    .stat-label-text { font-size: 12px; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.5px; }
    .stat-icon-pill {
