      display: flex; align-items: center; justify-content: center; font-size: 17px;
    }
    .stat-main-number { font-size: 26px; font-weight: 800; color: #0f172a; margin-bottom: 6px; font-family: var(--font-mono); }
    .stat-trend-pill { display: inline-flex; align-items: center; gap: 4px; font-size: 11.5px; font-weight: 700; color: #059669; }
    .stat-trend-pill.neutral { color: #4f46e5; }

    .catalog-toolbar-panel {
      background: #ffffff; border: 1px solid #eef2f6; border-radius: 14px;
      padding: 14px 18px; display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 18px; flex-wrap: wrap;
      box-shadow: 0 2px 8px rgba(15, 23, 42, 0.02);
    }
    .filter-tabs-group { display: flex; gap: 6px; background: #f1f5f9; padding: 4px; border-radius: 10px; flex-wrap: wrap; }
    .filter-tab-btn {
      padding: 7px 14px; background: none; border: none; border-radius: 7px;
      color: #64748b; font-size: 12.5px; font-weight: 700; cursor: pointer; font-family: inherit; transition: all 0.2s;
    }
    .filter-tab-btn:hover { color: #0f172a; }
    .filter-tab-btn.active { background: #ffffff; color: #4f46e5; box-shadow: 0 1px 4px rgba(15, 23, 42, 0.08); }

    .search-input-box {
      height: 38px; padding: 0 14px 0 34px; background: #f8fafc;
      border: 1px solid #e2e8f0; border-radius: 9px; color: #0f172a; font-size: 13px; font-family: inherit; outline: none; width: 230px;
    }
    .search-input-box:focus { border-color: #6176fe; background: #ffffff; }
    .search-wrap { position: relative; display: flex; align-items: center; }
    .search-wrap .search-icon { position: absolute; left: 11px; color: #94a3b8; font-size: 13px; pointer-events: none; }

    .table-container-glass {
      background: #ffffff; border: 1px solid #eef2f6; border-radius: 14px;
      overflow-x: auto; box-shadow: 0 2px 10px rgba(15, 23, 42, 0.03);
    }
    .nexus-admin-table { width: 100%; border-collapse: collapse; text-align: left; }
    .nexus-admin-table th {
      padding: 13px 16px; background: #f1f4f9; border-bottom: 1px solid #e2e8f0;
      font-size: 12px; font-weight: 700; color: #334155;
    }
    .nexus-admin-table td { padding: 14px 16px; border-bottom: 1px solid #f1f5f9; font-size: 13px; color: #334155; vertical-align: middle; }
    .nexus-admin-table tr:hover td { background: #f8fafc; }

    .product-row-flex { display: flex; align-items: center; gap: 12px; }
    .product-thumb-img { width: 46px; height: 46px; border-radius: 8px; object-fit: contain; background: #f8fafc; border: 1px solid #e2e8f0; flex-shrink: 0; padding: 2px; }
    .product-title-bold { font-weight: 700; color: #0f172a; margin-bottom: 2px; max-width: 260px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .product-sku-code { font-size: 11px; font-family: var(--font-mono); color: #64748b; }

    .category-badge-pill { display: inline-block; padding: 4px 10px; border-radius: 6px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px; }
    .cat-shirts { background: #eff4ff; color: #4f46e5; border: 1px solid #dbeafe; }
    .cat-trousers { background: #ecfeff; color: #0891b2; border: 1px solid #cffafe; }
    .cat-shoes { background: #fffbeb; color: #d97706; border: 1px solid #fef3c7; }
    .cat-bags { background: #ecfdf5; color: #059669; border: 1px solid #d1fae5; }

    .views-badge-container { display: flex; gap: 6px; }
    .view-tag { padding: 3px 8px; border-radius: 5px; font-size: 11px; font-weight: 600; background: #f8fafc; border: 1px solid #e2e8f0; color: #64748b; display: inline-flex; align-items: center; gap: 4px; }
    .view-tag.has-view { background: #ecfdf5; border-color: #a7f3d0; color: #059669; }

    .price-flex-cell { display: flex; flex-direction: column; gap: 2px; }
    .final-price-bold { font-size: 14px; font-weight: 800; font-family: var(--font-mono); color: #0f172a; }
    .regular-price-struck { font-size: 11.5px; color: #94a3b8; text-decoration: line-through; }
    .discount-badge-mini { display: inline-block; padding: 2px 6px; background: #fff1f2; border: 1px solid #fecdd3; color: #e11d48; border-radius: 4px; font-size: 10px; font-weight: 800; margin-left: 6px; }

    .action-btn-row { display: flex; align-items: center; gap: 6px; }
    .btn-table-action { padding: 6px 11px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 7px; color: #334155; font-size: 12px; font-weight: 600; cursor: pointer; font-family: inherit; transition: all 0.2s; }
    .btn-table-action:hover { background: #eff4ff; border-color: #c7d2fe; color: #4f46e5; }
    .btn-table-delete:hover { background: #fff1f2; border-color: #fecdd3; color: #e11d48; }
    .btn-action-primary { padding: 9px 16px; background: #6176fe; color: #fff; border: none; border-radius: 8px; font-size: 12.5px; font-weight: 700; cursor: pointer; transition: all 0.2s; }
    .btn-action-primary:hover { background: #4f46e5; }
    .btn-logout { padding: 7px 14px; background: #fff1f2; border: 1px solid #fecdd3; border-radius: 8px; color: #e11d48; font-size: 12px; font-weight: 700; cursor: pointer; }
    .btn-logout:hover { background: #ffe4e6; }
    .order-status-badge { padding: 4px 10px; border-radius: 6px; font-size: 11px; font-weight: 700; display: inline-block; }
    .status-completed { background: #dcfce7; color: #16a34a; }
    .status-processing { background: #e0e7ff; color: #4f46e5; }
    .status-pending { background: #fef3c7; color: #d97706; }

    /* Marketing / Discounts Light Card */
    #section-discounts-view .stat-card-glass h4 { color: #0f172a; }
    #section-discounts-view > div { background: #ffffff !important; border-color: #eef2f6 !important; color: #0f172a; box-shadow: 0 2px 10px rgba(15,23,42,0.03); }
    #section-discounts-view p { color: #64748b !important; }

    /* MODAL */
    .modal-backdrop-overlay {
      position: fixed; top: 0; left: 0; right: 0; bottom: 0;
      background: rgba(0, 0, 0, 0.75); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
      z-index: 1000; display: none; align-items: center; justify-content: center; padding: 20px;
      overflow-y: auto;
    }
    .modal-box-card {
      width: 100%; max-width: 820px; max-height: 90vh; background: #0f1118;
      border: 1px solid var(--border-glass); border-radius: 24px;
      box-shadow: 0 30px 80px rgba(0, 0, 0, 0.8), 0 0 50px rgba(99, 102, 241, 0.15);
      display: flex; flex-direction: column; overflow: hidden;
    }
    #product-modal .modal-box-card {
      height: 88vh;
      max-height: 88vh;
    }
    .modal-header-bar {
      padding: 20px 28px; border-bottom: 1px solid var(--border-glass);
      display: flex; align-items: center; justify-content: space-between;
      background: rgba(255, 255, 255, 0.02); flex-shrink: 0;
    }
    .modal-title-text { font-size: 20px; font-weight: 800; }
    .modal-close-btn { background: none; border: none; color: var(--text-silver); font-size: 24px; cursor: pointer; padding: 4px; }
    .modal-close-btn:hover { color: #fff; }

    #product-edit-form {
      display: flex;
      flex-direction: column;
      flex: 1;
      min-height: 0;
      overflow: hidden;
    }

    .modal-body-scrollable {
      padding: 28px;
      overflow-y: auto;
      -webkit-overflow-scrolling: touch;
      flex: 1;
      min-height: 0;
      display: flex;
      flex-direction: column;
      gap: 24px;
      scrollbar-width: thin;
      scrollbar-color: rgba(255, 255, 255, 0.25) transparent;
    }
    .modal-body-scrollable::-webkit-scrollbar {
      width: 7px;
    }
    .modal-body-scrollable::-webkit-scrollbar-track {
      background: rgba(255, 255, 255, 0.02);
      border-radius: 8px;
    }
    .modal-body-scrollable::-webkit-scrollbar-thumb {
      background: rgba(255, 255, 255, 0.22);
      border-radius: 8px;
    }
    .modal-body-scrollable::-webkit-scrollbar-thumb:hover {
      background: rgba(255, 255, 255, 0.4);
    }
    .modal-form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }

    .category-selector-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
    .cat-radio-card { position: relative; }
    .cat-radio-card input { position: absolute; opacity: 0; width: 0; height: 0; }
    .cat-radio-label {
      display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 14px 10px;
      background: rgba(255, 255, 255, 0.03); border: 1px solid var(--border-glass); border-radius: 12px;
      color: var(--text-silver); font-size: 13px; font-weight: 700; cursor: pointer; transition: all 0.2s;
    }
    .cat-radio-label .cat-icon { font-size: 20px; }
    .cat-radio-card input:checked + .cat-radio-label {
      background: linear-gradient(135deg, rgba(99,102,241,0.25), rgba(59,130,246,0.2));
      border-color: var(--accent-primary); color: #fff; box-shadow: 0 4px 14px rgba(99, 102, 241, 0.25);
    }

    .photo-upload-section { background: rgba(255, 255, 255, 0.02); border: 1px solid var(--border-glass); border-radius: 16px; padding: 20px; }
    .photo-section-title { font-size: 14px; font-weight: 700; margin-bottom: 6px; display: flex; align-items: center; gap: 8px; }
    .photo-section-sub { font-size: 12.5px; color: var(--text-silver); margin-bottom: 16px; line-height: 1.4; }
    .photo-upload-dual-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }

    .upload-box-card {
      border: 2px dashed rgba(255, 255, 255, 0.15); border-radius: 14px; padding: 18px; text-align: center;
      background: rgba(0, 0, 0, 0.25); cursor: pointer; position: relative; transition: all 0.2s ease;
      min-height: 160px; display: flex; flex-direction: column; align-items: center; justify-content: center;
    }
    .upload-box-card:hover { border-color: var(--accent-primary); background: rgba(99, 102, 241, 0.05); }
    .upload-box-card input[type="file"] { position: absolute; top: 0; left: 0; right: 0; bottom: 0; opacity: 0; cursor: pointer; width: 100%; height: 100%; }
    .upload-placeholder-content { pointer-events: none; }
    .upload-placeholder-icon { font-size: 28px; margin-bottom: 8px; color: var(--text-silver); }
    .upload-box-preview-img { max-height: 130px; max-width: 100%; object-fit: contain; border-radius: 8px; margin-bottom: 8px; display: none; }

    .hanger-switch-card {
      display: flex; align-items: center; justify-content: space-between; padding: 14px 18px;
      background: rgba(99, 102, 241, 0.08); border: 1px solid rgba(99, 102, 241, 0.25); border-radius: 12px; margin-top: 14px;
    }
    .hanger-info-text h5 { font-size: 13.5px; font-weight: 700; color: #fff; margin-bottom: 2px; }
    .hanger-info-text p { font-size: 12px; color: var(--text-silver); }
    .toggle-switch-input { width: 44px; height: 24px; accent-color: var(--accent-primary); cursor: pointer; }

    .discount-calc-card {
      background: linear-gradient(135deg, rgba(244,63,94,0.08), rgba(99,102,241,0.08));
      border: 1px solid rgba(244, 63, 94, 0.25); border-radius: 14px; padding: 16px 20px;
      display: flex; align-items: center; justify-content: space-between;
    }
    .calc-row-item { display: flex; flex-direction: column; }
    .calc-label { font-size: 11px; font-weight: 700; color: var(--text-silver); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 2px; }
    .calc-val { font-size: 18px; font-weight: 900; font-family: var(--font-mono); color: #fff; }
    .calc-val.highlight { color: #34d399; }

    .modal-footer-bar {
      padding: 18px 28px;
      border-top: 1px solid var(--border-glass);
      background: rgba(255, 255, 255, 0.02);
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 12px;
      flex-shrink: 0;
    }
    .btn-modal-cancel { padding: 10px 20px; background: rgba(255, 255, 255, 0.05); border: 1px solid var(--border-glass); border-radius: 999px; color: var(--text-silver); font-size: 13px; font-weight: 700; cursor: pointer; font-family: inherit; }
    .btn-modal-save { padding: 10px 24px; background: #ffffff; color: #000000; border: none; border-radius: 999px; font-size: 13.5px; font-weight: 800; cursor: pointer; font-family: inherit; }

    /* Toast */
    #admin-toast {
      position: fixed; bottom: 30px; right: 30px; padding: 14px 22px;
      background: #0f1118; border: 1px solid var(--border-focus); border-radius: 14px; color: #fff;
      font-size: 13.5px; font-weight: 700; display: flex; align-items: center; gap: 12px;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.7), 0 0 25px rgba(99, 102, 241, 0.3);
      z-index: 9999; transform: translateY(100px); opacity: 0; transition: all 0.3s ease; pointer-events: none;
    }
    #admin-toast.show { transform: translateY(0); opacity: 1; }

/* === TRY THE LOOK DUMMIES ADMIN PANEL === */
.looks-checkerboard {
  background-color: #f8f7f4;
  background-image:
    linear-gradient(45deg, #eae7e0 25%, transparent 25%),
    linear-gradient(-45deg, #eae7e0 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #eae7e0 75%),
    linear-gradient(-45deg, transparent 75%, #eae7e0 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
}
.looks-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 18px;
  margin-top: 16px;
}
.look-admin-card {
  background: #ffffff;
  border: 1px solid #e6e4df;
  border-radius: 14px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
  transition: transform 0.2s, box-shadow 0.2s;
}
.look-admin-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 26px rgba(15, 23, 42, 0.08);
}
.look-card-stage {
