    function renderCategoryDonutChart(items, orders, totalOrderRevenue) {
      const svgContainer = document.getElementById('donut-svg-container');
      const legendContainer = document.getElementById('donut-legend-container');
      if (!svgContainer || !legendContainer) return;

      if (!items) items = window.NexusCatalog ? window.NexusCatalog.getAll() : [];
      if (!orders) orders = window.NexusCatalog ? window.NexusCatalog.getOrders() : [];

      // Calculate real category sales from orders
      let catRevenue = { shoes: 149.00, trousers: 130.50, shirts: 109.65, bags: 0.00 };
      let totalSales = totalOrderRevenue || 389.15;

      const dynamicCatRev = { shoes: 0, trousers: 0, shirts: 0, bags: 0 };
      let dynamicTotal = 0;

      orders.forEach(o => {
        (o.items || []).forEach(it => {
          const p = items.find(x => x.id === it.id);
          const cat = p ? p.category : (it.id.includes('shoe') ? 'shoes' : it.id.includes('shirt') ? 'shirts' : it.id.includes('trouser') ? 'trousers' : 'bags');
          const cost = parseFloat(it.price || 0) * (it.quantity || 1);
          if (dynamicCatRev[cat] !== undefined) dynamicCatRev[cat] += cost;
          else dynamicCatRev.bags += cost;
          dynamicTotal += cost;
        });
      });

      if (dynamicTotal > 0) {
        catRevenue = dynamicCatRev;
        totalSales = dynamicTotal;
      }

      const pShoes = Math.round((catRevenue.shoes / totalSales) * 100) || 38;
      const pTrousers = Math.round((catRevenue.trousers / totalSales) * 100) || 34;
      const pShirts = Math.max(0, 100 - pShoes - pTrousers);

      const cats = [
        { key: 'shoes', name: 'Footwear Orbit', color: '#ff7828', percent: pShoes, amount: '$' + catRevenue.shoes.toFixed(2) },
        { key: 'trousers', name: 'Denim & Trousers', color: '#f59e0b', percent: pTrousers, amount: '$' + catRevenue.trousers.toFixed(2) },
        { key: 'shirts', name: 'Shirts & Tops', color: '#181920', percent: pShirts, amount: '$' + catRevenue.shirts.toFixed(2) },
        { key: 'bags', name: 'Bags & Carry', color: '#cbd5e1', percent: 0, amount: '$0.00' }
      ];

      const r = 58;
      const C = 2 * Math.PI * r;
      let offset = 0;
      let circlesSvg = '';
      let legendHtml = '';

      cats.forEach(c => {
        if (c.percent > 0) {
          const dash = (c.percent / 100) * C;
          const gap = C - dash;
          circlesSvg += `
            <circle cx="90" cy="90" r="${r}" fill="none" stroke="${c.color}" stroke-width="26"
              stroke-dasharray="${dash} ${gap}" stroke-dashoffset="${-offset}"
              style="transition: all 0.5s ease;" />
          `;
          offset += dash;
        }

        legendHtml += `
          <div class="donut-legend-item">
            <div class="legend-left">
              <span class="legend-dot" style="background-color: ${c.color};"></span>
              <span>${c.name}</span>
            </div>
            <span class="legend-percent">${c.percent}%</span>
          </div>
        `;
      });

      svgContainer.innerHTML = `
        <svg viewBox="0 0 180 180" width="100%" height="100%">
          <g transform="rotate(-90 90 90)">
            ${circlesSvg}
          </g>
          <text x="90" y="86" text-anchor="middle" font-size="19" font-weight="900" fill="#0f172a" font-family="'Space Grotesk', sans-serif">$${totalSales.toFixed(2)}</text>
          <text x="90" y="104" text-anchor="middle" font-size="10.5" font-weight="600" fill="#94a3b8">Total Sales</text>
        </svg>
      `;

      legendContainer.innerHTML = legendHtml;
    }

