    function renderStatsCards() {
      const items = window.NexusCatalog ? window.NexusCatalog.getAll() : [];
      const orders = window.NexusCatalog ? window.NexusCatalog.getOrders() : [];

      let totalVal = 0;
      let totalDiscountSum = 0;
      let discountedCount = 0;

      items.forEach(p => {
        const price = parseFloat(p.price) || 0;
        const stock = parseInt(p.stock) || 0;
        totalVal += (price * stock);
        const disc = parseFloat(p.discountPercent) || 0;
        if (disc > 0) {
          totalDiscountSum += disc;
          discountedCount++;
        }
      });

      const avgDisc = discountedCount > 0 ? Math.round(totalDiscountSum / discountedCount) : 0;

      const elVal = document.getElementById('stat-total-value');
      if (elVal) elVal.innerText = '$' + totalVal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      const elProds = document.getElementById('stat-total-products');
      if (elProds) elProds.innerText = items.length;
      const elPend = document.getElementById('stat-pending-orders');
      if (elPend) elPend.innerText = orders.length;
      const elAvg = document.getElementById('stat-avg-discount');
      if (elAvg) elAvg.innerText = avgDisc + '%';
      const elTrend = document.getElementById('stat-discount-trend');
      if (elTrend) elTrend.innerText = `✦ ${discountedCount} pieces currently on promotion`;
    }

