    function getCategorySkuPrefix(cat) {
      switch (cat) {
        case 'shirts': return 'SH';
        case 'trousers': return 'TR';
        case 'shoes': return 'SN';
        case 'bags': return 'BG';
        default: return (cat || 'IT').substring(0, 2).toUpperCase();
      }
    }

    function getNextSequentialSku(cat) {
      if (!cat) {
        cat = document.querySelector('input[name="prod-category"]:checked')?.value || 'shirts';
      }
      const prefix = getCategorySkuPrefix(cat);
      const all = window.NexusCatalog ? window.NexusCatalog.getAll() : [];
      let maxSeq = 0;
      const regex = new RegExp(`^NX-${prefix}-(\\d{4,})$`, 'i');
      all.forEach(p => {
        if (!p || !p.sku) return;
        const m = p.sku.trim().match(regex);
        if (m) {
          const val = parseInt(m[1], 10);
          if (!isNaN(val) && val > maxSeq) {
            maxSeq = val;
          }
        }
      });
      const nextSeq = maxSeq + 1;
      return `NX-${prefix}-${String(nextSeq).padStart(4, '0')}`;
    }

    function generateAutoSku(cat) {
      const candidate = getNextSequentialSku(cat);
      const input = document.getElementById('form-sku');
      if (input) {
        input.value = candidate;
      }
      return candidate;
    }

