    function updatePriceCalculationPreview() {
      const reg = parseFloat(document.getElementById('form-price').value) || 0;
      const disc = Math.max(0, Math.min(90, parseFloat(document.getElementById('form-discount').value) || 0));
      const calc = window.NexusCatalog.calculatePrice(reg, disc);

      document.getElementById('calc-preview-reg').innerText = '$' + calc.regular.toFixed(2);
      document.getElementById('calc-preview-disc').innerText = calc.discount + '%';
      document.getElementById('calc-preview-save').innerText = '$' + calc.savings.toFixed(2);
      document.getElementById('calc-preview-final').innerText = '$' + calc.final.toFixed(2);
    }

    function handleImageFileSelected(input, targetView) {
      if (!input.files || !input.files[0]) return;
      const file = input.files[0];
      const category = document.querySelector('input[name="prod-category"]:checked')?.value || 'shirts';
      const reader = new FileReader();

      reader.onload = function(e) {
        const base64Data = e.target.result;

        // Show immediate raw preview
        if (targetView === 'front') {
          document.getElementById('form-front-url').value = base64Data;
          document.getElementById('img-preview-front').src = base64Data;
          document.getElementById('img-preview-front').style.display = 'block';
          document.getElementById('placeholder-front').style.display = 'none';
        } else {
          document.getElementById('form-side-url').value = base64Data;
          document.getElementById('img-preview-side').src = base64Data;
          document.getElementById('img-preview-side').style.display = 'block';
          document.getElementById('placeholder-side').style.display = 'none';
        }

        // Real-time automatic background extraction on canvas
        if (window.HangerCompositor && (category === 'shirts' || category === 'trousers' || category === 'bags')) {
          showToast(category === 'bags' ? 'Removing bag background for 3D Pedestal...' : 'Extracting clothing cutout & removing background...');
          const tempImg = new Image();
          tempImg.onload = function() {
            try {
              const cutoutCanvas = window.HangerCompositor.extractGarmentCutout(tempImg, category);
              const cutoutDataUrl = cutoutCanvas.toDataURL('image/png', 0.95);
              if (targetView === 'front') {
                document.getElementById('form-front-url').value = cutoutDataUrl;
                document.getElementById('img-preview-front').src = cutoutDataUrl;
                showToast(category === 'bags' ? '3D Bag cutout extracted cleanly!' : 'Garment cutout extracted with transparent background!');
              } else {
                document.getElementById('form-side-url').value = cutoutDataUrl;
                document.getElementById('img-preview-side').src = cutoutDataUrl;
              }
            } catch (cutErr) {
              console.warn('[Cutout Error]', cutErr);
            }
          };
          tempImg.src = base64Data;
        }

        try {
          window.__nexusPendingUploads = window.__nexusPendingUploads || {};
          window.__nexusPendingUploads[targetView] = fetch('/api/upload', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ filename: file.name, image: base64Data, category: category, viewType: targetView })
          }).then(res => res.json()).then(data => {
            if (data.url) {
              if (targetView === 'front') {
                document.getElementById('form-front-url').value = data.url;
                document.getElementById('img-preview-front').src = data.url;
              } else {
                document.getElementById('form-side-url').value = data.url;
                document.getElementById('img-preview-side').src = data.url;
              }
            }
          }).catch(() => {}).finally(() => {
            if (window.__nexusPendingUploads) delete window.__nexusPendingUploads[targetView];
          });
        } catch (err) {}
      };

      reader.readAsDataURL(file);
    }

    async function handleSaveProduct() {
      if (window.__nexusPendingUploads && Object.keys(window.__nexusPendingUploads).length > 0) {
        showToast('Finalizing Python garment cutout...');
        await Promise.allSettled(Object.values(window.__nexusPendingUploads));
      }
      const editId = document.getElementById('form-edit-id').value;
      const category = document.querySelector('input[name="prod-category"]:checked').value;
      const title = document.getElementById('form-title').value.trim();
      if (!title) {
        showToast('Please enter a product title!');
        return;
      }
      let sku = document.getElementById('form-sku').value.trim();
      if (!sku) {
        sku = generateAutoSku(category);
      }
      const price = parseFloat(document.getElementById('form-price').value) || 0;
      const discount = parseFloat(document.getElementById('form-discount').value) || 0;
      const stock = parseInt(document.getElementById('form-stock').value) || 20;
      const sizesStr = document.getElementById('form-sizes').value.trim();
      const sizes = sizesStr ? sizesStr.split(',').map(s => s.trim()) : ['S', 'M', 'L', 'XL'];
      const description = document.getElementById('form-description').value.trim();
      const hangerDefault = document.getElementById('form-hanger-default').checked;

      let front = document.getElementById('form-front-url').value;
      let side = document.getElementById('form-side-url').value;

      if (!front) {
        front = category === 'trousers' 
          ? 'rail_assets/trousers_cutouts/4_cut.png' 
          : 'rail_assets/shirts/shirt_beige_utility.jpg';
      }

      let frontRail = front;
      let sideRail = side;

      const frontIsPyCutout = /_cutout\.png$/i.test(front || '');
      const sideIsPyCutout = !side || /_cutout\.png$/i.test(side);

      // Automatically composite with Master Hanger if category is shirts or trousers (skip if Python /api/upload already composited)
      if ((category === 'shirts' || category === 'trousers') && window.HangerCompositor && (!frontIsPyCutout || !sideIsPyCutout || !hangerDefault)) {
        try {
          showToast('Mounting onto 3D Master Rail Hanger...');
          const processed = await window.HangerCompositor.processGarmentDualViews(
            frontIsPyCutout ? front : front,
            side,
            category,
            hangerDefault
          );
          if (!frontIsPyCutout || !hangerDefault) frontRail = processed.frontView;
          if (side && !sideIsPyCutout) sideRail = processed.sideView;
        } catch (compErr) {
          console.warn('[Admin] Compositing error:', compErr);
        }
      }

      if (!sideRail) {
        sideRail = (side && side.trim()) ? side : frontRail;
      }

      const productPayload = {
        title: title,
        category: category,
        sku: sku,
        price: price,
        discountPercent: discount,
        stock: stock,
        sizes: sizes,
        image: front, // for catalog grids
        rawFrontView: front,
        rawSideView: side,
        frontView: frontRail, // for 3D Runway Rail
        sideView: sideRail,   // for 3D Runway Rail
        hangerType: 'master_front_hanger_official.png',
        hangerDefault: hangerDefault,
        description: description
      };

      if (editId) {
        showToast(`Syncing "${title}" to database...`);
        await window.NexusCatalog.updateProduct(editId, productPayload);
        showToast(`Piece "${title}" updated on live store & database!`);
      } else {
        showToast(`Publishing "${title}" to database & 3D rail...`);
        await window.NexusCatalog.addProduct(productPayload);
        showToast(`Piece "${title}" saved to database & mounted to 3D rail!`);
      }

      closeProductModal();
      refreshAllDashboardViews();
    }

