    // ==================== EXECUTIVE PDF REPORT ENGINE ====================
    function createNexusPdfDoc(reportTitle, subtitle) {
      const jsPDF = (window.jspdf && window.jspdf.jsPDF) ? window.jspdf.jsPDF : window.jsPDF;
      if (!jsPDF) {
        showToast('PDF engine loading... please retry in a moment.');
        return null;
      }
      const doc = new jsPDF({ orientation: 'portrait', unit: 'pt', format: 'a4' });
      const pageW = doc.internal.pageSize.getWidth();

      // Luxury dark header banner
      doc.setFillColor(14, 16, 23);
      doc.rect(0, 0, pageW, 86, 'F');
      doc.setFillColor(201, 169, 110);
      doc.rect(0, 84, pageW, 2.5, 'F');

      doc.setTextColor(255, 255, 255);
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(18);
      doc.text('NEXUS ATELIER', 36, 36);

      doc.setTextColor(226, 192, 130);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(9.5);
      doc.text((reportTitle || 'ADMINISTRATION REPORT').toUpperCase(), 36, 54);

      doc.setTextColor(180, 188, 200);
      doc.setFontSize(8.5);
      doc.text(subtitle || 'Haute-Couture Master Administration', 36, 70);

      const stamp = new Date().toLocaleString();
      const adminLabel = currentUser ? `${currentUser.name} (${currentUser.roleLabel})` : 'Super Administrator';
      doc.setTextColor(200, 205, 215);
      doc.text(`Generated: ${stamp}`, pageW - 36, 42, { align: 'right' });
      doc.text(`Authorized: ${adminLabel}`, pageW - 36, 58, { align: 'right' });

      return doc;
    }

    function finalizeNexusPdf(doc, filename) {
      const totalPages = doc.internal.getNumberOfPages();
      const pageW = doc.internal.pageSize.getWidth();
      const pageH = doc.internal.pageSize.getHeight();
      for (let i = 1; i <= totalPages; i++) {
        doc.setPage(i);
        doc.setDrawColor(225, 228, 232);
        doc.line(36, pageH - 36, pageW - 36, pageH - 36);
        doc.setFontSize(8);
        doc.setTextColor(120, 128, 140);
        doc.text('NEXUS ATELIER CONFIDENTIAL — LIVE DATABASE SNAPSHOT', 36, pageH - 22);
        doc.text(`Page ${i} of ${totalPages}`, pageW - 36, pageH - 22, { align: 'right' });
      }
      doc.save(filename);
      showToast(`Exported ${filename}`);
    }

    function resolveActiveAdminSection() {
      const secOrders = document.getElementById('section-orders-view');
      const secDiscounts = document.getElementById('section-discounts-view');
      if (secOrders && secOrders.style.display !== 'none') return 'orders';
      if (secDiscounts && secDiscounts.style.display !== 'none') return 'discounts';
      return 'products';
    }

    function addSectionHeading(doc, text, y) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(12);
      doc.setTextColor(17, 24, 39);
      doc.text(text, 36, y);
      return y + 10;
    }

    function appendOverviewSectionToPdf(doc, startY, items, orders) {
      let y = addSectionHeading(doc, '1. Sales & Catalog Executive Summary', startY);
      let totalCatalogVal = 0;
      let totalDiscountSum = 0;
      const catCounts = { shirts: 0, trousers: 0, shoes: 0, bags: 0 };
      const catValues = { shirts: 0, trousers: 0, shoes: 0, bags: 0 };

      items.forEach(p => {
        const calc = window.NexusCatalog.calculatePrice(p.price, p.discountPercent);
        totalCatalogVal += calc.final;
        totalDiscountSum += calc.discount;
        if (catCounts[p.category] !== undefined) {
          catCounts[p.category]++;
          catValues[p.category] += calc.final;
        }
      });
      const totalOrderRev = orders.reduce((sum, o) => sum + (parseFloat(o.total) || 0), 0);
      const pendingOrders = orders.filter(o => o.status === 'Under Review' || o.status === 'Processing').length;
      const avgDisc = items.length ? (totalDiscountSum / items.length).toFixed(1) : '0.0';

      doc.autoTable({
        startY: y,
        head: [['Metric', 'Live Value', 'Notes']],
        body: [
          ['Total Order Revenue', `$${totalOrderRev.toFixed(2)}`, `${orders.length} total client orders`],
          ['Pending Orders', `${pendingOrders}`, 'Under Review / Processing'],
          ['Active Catalog Pieces', `${items.length}`, 'Shirts, Trousers, Footwear & Bags'],
          ['Total Catalog Valuation', `$${totalCatalogVal.toFixed(2)}`, 'After promotional discounts'],
          ['Average Discount Tier', `${avgDisc}%`, 'Across active archive items']
        ],
        theme: 'grid',
        headStyles: { fillColor: [17, 24, 39], textColor: 255, fontSize: 9 },
        styles: { fontSize: 8.5, cellPadding: 6 },
        margin: { left: 36, right: 36 }
      });

      y = doc.lastAutoTable.finalY + 20;
      y = addSectionHeading(doc, 'Category Inventory Breakdown', y);
      doc.autoTable({
        startY: y,
        head: [['Category', 'Pieces', 'Net Valuation ($)', 'Avg Piece Price ($)']],
        body: ['shirts', 'trousers', 'shoes', 'bags'].map(c => {
          const cnt = catCounts[c];
          const val = catValues[c];
          return [c.toUpperCase(), String(cnt), `$${val.toFixed(2)}`, `$${(cnt ? val / cnt : 0).toFixed(2)}`];
        }),
        theme: 'striped',
        headStyles: { fillColor: [79, 70, 229], textColor: 255, fontSize: 9 },
        styles: { fontSize: 8.5, cellPadding: 5 },
        margin: { left: 36, right: 36 }
      });
      return doc.lastAutoTable.finalY + 22;
    }

    function appendProductsSectionToPdf(doc, startY, items) {
