        startY: y,
        head: [['SKU', 'Product Title', 'Category', 'Regular', 'Disc.', 'Final', 'Stock', 'Sizes']],
        body: rows.length ? rows : [['—', 'No products match current filter', '—', '—', '—', '—', '—', '—']],
