    function generateAdminPdfReport(scope) {
      const resolvedScope = scope === 'active' ? resolveActiveAdminSection() : (scope || 'full');
      const allItems = window.NexusCatalog ? window.NexusCatalog.getAll() : [];
      const orders = window.NexusCatalog ? window.NexusCatalog.getOrders() : [];
      const dateSlug = new Date().toISOString().slice(0, 10);

      let filteredItems = allItems;
      if (resolvedScope === 'products') {
        if (currentFilter && currentFilter !== 'all') {
          filteredItems = filteredItems.filter(p => p.category === currentFilter);
        }
        if (currentSearchQuery && currentSearchQuery.trim()) {
          const q = currentSearchQuery.trim().toLowerCase();
          filteredItems = filteredItems.filter(p =>
            (p.title || '').toLowerCase().includes(q) || (p.sku || '').toLowerCase().includes(q)
          );
        }
      }

      const titles = {
        overview: ['Sales & Analytics Report', 'Real-Time Revenue, Orders & Category Valuation'],
        products: ['Catalog & Inventory Report', `Filter: ${(currentFilter || 'all').toUpperCase()}`],
        orders: ['Client Orders & Fulfillment Report', 'Orders, Payments & Bank Slip Verification'],
        discounts: ['Discounts & Marketing Matrix', 'Active Promotional Margins & Client Savings'],
        full: ['Master Executive Report', 'Complete Sales, Inventory, Orders & Discounts Snapshot']
      };
      const [title, sub] = titles[resolvedScope] || titles.full;
      const doc = createNexusPdfDoc(title, sub);
      if (!doc) return;

      let y = 110;
      if (resolvedScope === 'overview') {
        y = appendOverviewSectionToPdf(doc, y, allItems, orders);
        appendOrdersSectionToPdf(doc, y, orders.slice(0, 10));
      } else if (resolvedScope === 'products') {
        appendProductsSectionToPdf(doc, y, filteredItems);
      } else if (resolvedScope === 'orders') {
        appendOrdersSectionToPdf(doc, y, orders);
      } else if (resolvedScope === 'discounts') {
        appendDiscountsSectionToPdf(doc, y, allItems);
      } else {
        y = appendOverviewSectionToPdf(doc, y, allItems, orders);
        doc.addPage();
        y = 48;
        y = appendProductsSectionToPdf(doc, y, allItems);
        doc.addPage();
        y = 48;
        y = appendOrdersSectionToPdf(doc, y, orders);
        appendDiscountsSectionToPdf(doc, y, allItems);
      }

      finalizeNexusPdf(doc, `NEXUS_${resolvedScope}_Report_${dateSlug}.pdf`);
    }

