        ]],
        theme: 'grid',
        headStyles: { fillColor: [17, 24, 39], textColor: 255, fontSize: 9 },
        styles: { fontSize: 8.5, cellPadding: 8 },
        margin: { left: 36, right: 36 }
      });

      const itemRows = (order.items || []).map(it => {
        const qty = parseInt(it.quantity, 10) || 1;
        const unit = parseFloat(it.price) || 0;
        return [it.title || 'Atelier Piece', it.size || 'M', String(qty), `$${unit.toFixed(2)}`, `$${(qty * unit).toFixed(2)}`];
      });

      doc.autoTable({
        startY: doc.lastAutoTable.finalY + 18,
        head: [['Atelier Piece', 'Size', 'Qty', 'Unit Price', 'Line Total']],
        body: itemRows.length ? itemRows : [['Order Item', '—', '1', `$${parseFloat(order.total || 0).toFixed(2)}`, `$${parseFloat(order.total || 0).toFixed(2)}`]],
        foot: [['', '', '', 'TOTAL PAYABLE', `$${parseFloat(order.total || 0).toFixed(2)}`]],
        theme: 'striped',
        headStyles: { fillColor: [79, 70, 229], textColor: 255, fontSize: 9 },
        footStyles: { fillColor: [17, 24, 39], textColor: [226, 192, 130], fontStyle: 'bold', fontSize: 9.5 },
        styles: { fontSize: 8.5, cellPadding: 6 },
        margin: { left: 36, right: 36 }
      });

      finalizeNexusPdf(doc, `NEXUS_Invoice_${order.id}.pdf`);
    }

    // ================= TRY THE LOOK DUMMIES MANAGER =================
    let nexusCustomLooks = [];
    let currentLookKitItems = [];
    let pendingKitUploads = 0;

    async function loadRunwayLooksAdmin() {
      try {
        const res = await fetch('/api/looks', { cache: 'no-store' });
        if (res.ok) {
          nexusCustomLooks = await res.json();
          if (!Array.isArray(nexusCustomLooks)) nexusCustomLooks = [];
        }
      } catch (err) {
        console.warn('[Looks Load Error]', err);
      }
      const badge = document.getElementById('badge-count-looks');
      if (badge) badge.innerText = String(nexusCustomLooks.length);
      renderRunwayLooksGrid();
    }

    function renderRunwayLooksGrid() {
      const grid = document.getElementById('looks-cards-grid');
      if (!grid) return;
      if (!nexusCustomLooks.length) {
        grid.innerHTML = '<div style="grid-column:1/-1; background:#ffffff; border:1px dashed #cbd5e1; border-radius:14px; padding:34px; text-align:center; color:#64748b;">No custom Runway Dummies yet. Click <strong>+ Add Runway Dummy</strong> to upload a dummy photo (background automatically removed via AI) and add its exact outfit kit &amp; prices!</div>';
        return;
      }

      grid.innerHTML = nexusCustomLooks.map((lk, i) => {
        const imgSrc = lk.image && lk.image.startsWith('/') ? lk.image : '/' + (lk.image || '').replace(/^\.?\//, '');
        const kitCount = (Array.isArray(lk.kitItems) && lk.kitItems.length)
          ? lk.kitItems.length
          : (Array.isArray(lk.linkedProductIds) ? lk.linkedProductIds.length : 0);
        return `
          <div class="look-admin-card">
            <div class="look-card-stage looks-checkerboard">
              <span style="position:absolute; top:10px; left:10px; background:#151413; color:#fff; font-size:10px; font-weight:700; padding:3px 8px; border-radius:999px;">LOOK ${String(1 + i).padStart(2, '0')}</span>
              <img src="${imgSrc}" alt="${(lk.name || '').replace(/"/g, '&quot;')}" />
            </div>
            <div class="look-card-body">
              <span class="look-card-tag">${kitCount} kit piece${kitCount === 1 ? '' : 's'}</span>
              <h4 class="look-card-title">${lk.name || 'Custom Dummy'}</h4>
              <div class="look-card-sub">${lk.subtitle || 'Custom Runway Dummy'}</div>
              <div class="look-card-actions">
                <button type="button" class="btn-table-action" onclick="openLookModal('${lk.id}')">Edit</button>
                <button type="button" class="btn-table-action" style="color:#dc2626; border-color:#fecaca;" onclick="deleteRunwayLook('${lk.id}')">Delete</button>
              </div>
            </div>
          </div>
        `;
      }).join('');
    }

    function populateCatalogQuickPick() {
      const sel = document.getElementById('look-catalog-quick-pick');
      if (!sel) return;
      const prods = window.NexusCatalog ? window.NexusCatalog.getAll() : [];
      sel.innerHTML = '<option value="">+ Optional: Import an existing piece from Store Catalog...</option>' +
        prods.map(p => `<option value="${p.id}">${p.title} ($${Number(p.price || 0).toFixed(2)})</option>`).join('');
    }

    function renderKitItemRows() {
      const box = document.getElementById('look-kit-rows');
      if (!box) return;
      if (!currentLookKitItems.length) {
        box.innerHTML = '<div style="text-align:center; padding:18px; color:#64748b; font-size:12.5px; border:1px dashed #cbd5e1; border-radius:10px;">Upload a Dummy photo (or click <strong>+ Add Piece</strong>) to set the exact clothes &amp; prices shown in "In this look".</div>';
        return;
      }
      box.innerHTML = currentLookKitItems.map((it, idx) => {
        const thumbSrc = it.image
          ? ((it.image.startsWith('/') || it.image.startsWith('http') || it.image.startsWith('data:')) ? it.image : '/' + it.image.replace(/^\.?\//, ''))
          : '';
        return `
          <div class="look-kit-row" data-kit-idx="${idx}">
            <div class="look-kit-thumb-wrap">
              <div class="look-kit-thumb looks-checkerboard">
                ${thumbSrc ? `<img id="kit-thumb-${idx}" src="${thumbSrc}" alt="" />` : `<span style="font-size:10px;color:#94a3b8;">Photo</span>`}
              </div>
              <label class="look-kit-upload-lbl">
                Upload
                <input type="file" accept="image/*" style="display:none;" onchange="handleKitPieceFileSelected(this, ${idx})" />
              </label>
            </div>
            <div class="look-kit-fields">
              <select onchange="updateKitItemField(${idx}, 'categoryLabel', this.value)">
                <option value="SHIRTS" ${it.categoryLabel === 'SHIRTS' ? 'selected' : ''}>SHIRTS / TOP</option>
                <option value="TROUSERS" ${it.categoryLabel === 'TROUSERS' ? 'selected' : ''}>TROUSERS / DENIM</option>
                <option value="SHOES" ${it.categoryLabel === 'SHOES' ? 'selected' : ''}>SHOES / SNEAKERS</option>
                <option value="OUTERWEAR" ${it.categoryLabel === 'OUTERWEAR' ? 'selected' : ''}>OUTERWEAR</option>
                <option value="ACCESSORIES" ${it.categoryLabel === 'ACCESSORIES' ? 'selected' : ''}>BAG / ACC</option>
              </select>
              <input type="text" placeholder="Exact piece title (e.g. Cream Knit Sweater)" value="${(it.title || '').replace(/"/g, '&quot;')}" oninput="updateKitItemField(${idx}, 'title', this.value)" />
              <input type="number" step="0.01" min="0" placeholder="Price $" value="${it.price || ''}" oninput="updateKitItemField(${idx}, 'price', parseFloat(this.value) || 0)" />
              <div style="grid-column:1/-1; display:flex; gap:6px; align-items:center; font-size:11px; color:#64748b;">
                <span>Sizes:</span>
                <input type="text" style="padding:4px 8px; font-size:11.5px;" placeholder="S, M, L, XL" value="${Array.isArray(it.sizes) ? it.sizes.join(', ') : (it.sizes || 'S, M, L, XL')}" oninput="updateKitItemSizes(${idx}, this.value)" />
              </div>
            </div>
            <button type="button" onclick="removeKitItemRow(${idx})" title="Remove piece" style="background:none; border:none; color:#dc2626; font-weight:700; cursor:pointer; font-size:15px;">✕</button>
          </div>
        `;
      }).join('');
    }

    function updateKitItemField(idx, field, val) {
      if (!currentLookKitItems[idx]) return;
      currentLookKitItems[idx][field] = val;
    }

    function updateKitItemSizes(idx, val) {
      if (!currentLookKitItems[idx]) return;
      const arr = String(val || '').split(',').map(s => s.trim()).filter(Boolean);
      currentLookKitItems[idx].sizes = arr.length ? arr : ['One Size'];
    }

    function addKitItemRow(prefill) {
      const idx = currentLookKitItems.length;
      const defaults = [
        { categoryLabel: 'SHIRTS', title: '', price: 85, sizes: ['S', 'M', 'L', 'XL'], pinTop: '34%', pinLeft: '48%' },
        { categoryLabel: 'TROUSERS', title: '', price: 115, sizes: ['30', '32', '34', '36'], pinTop: '62%', pinLeft: '48%' },
        { categoryLabel: 'SHOES', title: '', price: 145, sizes: ['40', '41', '42', '43', '44'], pinTop: '88%', pinLeft: '49%' },
      ];
      const base = defaults[idx % defaults.length];
      currentLookKitItems.push(Object.assign({
        id: 'kit-' + Date.now().toString(36) + '-' + idx,
        image: '',
      }, base, prefill || {}));
      renderKitItemRows();
    }

    function removeKitItemRow(idx) {
      currentLookKitItems.splice(idx, 1);
      renderKitItemRows();
    }

    function importCatalogPieceIntoKit(sel) {
      const pid = sel.value;
      if (!pid) return;
      const prods = window.NexusCatalog ? window.NexusCatalog.getAll() : [];
      const p = prods.find(x => x.id === pid);
      if (p) {
        const calc = window.NexusCatalog.calculatePrice(p.price, p.discountPercent);
        addKitItemRow({
          id: 'kit-' + Date.now().toString(36) + '-' + currentLookKitItems.length,
          title: p.title,
          categoryLabel: String(p.category || 'SHIRTS').toUpperCase(),
          price: calc.final,
          image: p.frontView || p.image || '',
          sizes: Array.isArray(p.sizes) && p.sizes.length ? p.sizes : ['S', 'M', 'L', 'XL'],
        });
      }
      sel.value = '';
    }

    function handleKitPieceFileSelected(input, idx) {
      if (!input.files || !input.files[0] || !currentLookKitItems[idx]) return;
      const file = input.files[0];
      const reader = new FileReader();
      reader.onload = function(e) {
        const b64 = e.target.result;
        currentLookKitItems[idx].image = b64;
        renderKitItemRows();
        pendingKitUploads++;
        showToast('Removing piece background cleanly...');
        fetch('/api/upload', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ filename: file.name, image: b64, category: 'bags', viewType: 'front' })
        }).then(r => r.json()).then(data => {
          if (data && data.url && currentLookKitItems[idx]) {
            currentLookKitItems[idx].image = data.url;
            renderKitItemRows();
            showToast('Kit piece cutout ready!');
          }
        }).catch(() => {}).finally(() => { pendingKitUploads = Math.max(0, pendingKitUploads - 1); });
      };
      reader.readAsDataURL(file);
    }

    function sliceRegionCanvas(img, yStartRatio, yEndRatio) {
      const iw = img.naturalWidth || img.width;
      const ih = img.naturalHeight || img.height;
      const sy = Math.floor(ih * yStartRatio);
      const sh = Math.max(20, Math.floor(ih * (yEndRatio - yStartRatio)));
      const c = document.createElement('canvas');
      c.width = 400;
      c.height = 400;
      const ctx = c.getContext('2d');
      const tmp = document.createElement('canvas');
      tmp.width = iw;
      tmp.height = sh;
      tmp.getContext('2d').drawImage(img, 0, sy, iw, sh, 0, 0, iw, sh);
      // Fit centered inside 400x400 square
      const scale = Math.min(360 / iw, 360 / sh);
      const dw = Math.round(iw * scale), dh = Math.round(sh * scale);
      ctx.drawImage(tmp, 0, 0, iw, sh, Math.round((400 - dw) / 2), Math.round((400 - dh) / 2), dw, dh);
      return c.toDataURL('image/png');
    }

    function autoCropKitFromDummy(onlyIfEmpty) {
      const imgUrl = document.getElementById('look-form-img-url').value.trim();
      if (!imgUrl) {
        if (!onlyIfEmpty) showToast('Upload a Dummy photo first!');
        return;
      }
      if (onlyIfEmpty && currentLookKitItems.some(it => it.title && it.title.trim())) return;
      const src = (imgUrl.startsWith('/') || imgUrl.startsWith('http') || imgUrl.startsWith('data:'))
        ? imgUrl
        : '/' + imgUrl.replace(/^\.?\//, '');
      const im = new Image();
      im.crossOrigin = 'anonymous';
      im.onload = function() {
        try {
          const topCrop = sliceRegionCanvas(im, 0.16, 0.50);
          const midCrop = sliceRegionCanvas(im, 0.44, 0.88);
          const shoeCrop = sliceRegionCanvas(im, 0.80, 0.99);
          if (!currentLookKitItems.length) {
            currentLookKitItems = [
              { id: 'kit-' + Date.now().toString(36) + '-0', categoryLabel: 'SHIRTS', title: 'Upper Garment', price: 95, image: topCrop, sizes: ['S', 'M', 'L', 'XL'], pinTop: '34%', pinLeft: '48%' },
              { id: 'kit-' + Date.now().toString(36) + '-1', categoryLabel: 'TROUSERS', title: 'Tailored Trousers', price: 120, image: midCrop, sizes: ['30', '32', '34', '36'], pinTop: '62%', pinLeft: '48%' },
              { id: 'kit-' + Date.now().toString(36) + '-2', categoryLabel: 'SHOES', title: 'Footwear', price: 145, image: shoeCrop, sizes: ['40', '41', '42', '43', '44'], pinTop: '88%', pinLeft: '49%' },
            ];
          } else {
            const crops = [topCrop, midCrop, shoeCrop];
            currentLookKitItems.forEach((it, idx) => {
              if (!it.image && crops[idx % 3]) it.image = crops[idx % 3];
            });
          }
          renderKitItemRows();
          if (!onlyIfEmpty) showToast('Extracted Top, Trousers & Shoes visuals from Dummy!');
        } catch (err) {
          console.warn('[AutoCrop Err]', err);
        }
      };
      im.src = src;
    }

    function openLookModal(lookId) {
      const existing = lookId ? nexusCustomLooks.find(x => x.id === lookId) : null;
      document.getElementById('look-modal-title').innerText = existing ? 'Edit Runway Dummy & Outfit Kit' : 'Add Try the Look Runway Dummy';
      document.getElementById('look-edit-id').value = existing ? existing.id : '';
      document.getElementById('look-form-name').value = existing ? (existing.name || '') : '';
      document.getElementById('look-form-subtitle').value = existing ? (existing.subtitle || 'Custom Runway Dummy') : 'Custom Runway Dummy';
      document.getElementById('look-form-img-url').value = existing ? (existing.image || '') : '';
      document.getElementById('look-file-input').value = '';

      const prods = window.NexusCatalog ? window.NexusCatalog.getAll() : [];
      if (existing && Array.isArray(existing.kitItems) && existing.kitItems.length) {
        currentLookKitItems = existing.kitItems.map(k => Object.assign({}, k));
      } else if (existing && Array.isArray(existing.linkedProductIds) && existing.linkedProductIds.length) {
        currentLookKitItems = existing.linkedProductIds.map((pid, idx) => {
          const p = prods.find(x => x.id === pid);
          if (!p) return null;
          const calc = window.NexusCatalog.calculatePrice(p.price, p.discountPercent);
          return {
            id: p.id,
            title: p.title,
            categoryLabel: String(p.category || 'SHIRTS').toUpperCase(),
            price: calc.final,
            image: p.frontView || p.image || '',
            sizes: Array.isArray(p.sizes) && p.sizes.length ? p.sizes : ['S', 'M', 'L', 'XL'],
            pinTop: idx === 0 ? '34%' : idx === 1 ? '62%' : '88%',
            pinLeft: '48%',
          };
        }).filter(Boolean);
      } else {
        currentLookKitItems = [];
      }

      const prev = document.getElementById('look-preview-img');
      const ph = document.getElementById('look-preview-placeholder');
      const st = document.getElementById('look-bg-status');
      if (existing && existing.image) {
        prev.src = existing.image.startsWith('/') ? existing.image : '/' + existing.image.replace(/^\.?\//, '');
        prev.style.display = 'block';
        ph.style.display = 'none';
        st.innerText = 'Transparent dummy cutout ready. Upload a new photo to replace it.';
      } else {
        prev.src = '';
        prev.style.display = 'none';
        ph.style.display = 'block';
        st.innerHTML = 'Upload any photo — <code>u2net</code> AI automatically strips the background and fits the dummy to the runway stage.';
      }
      populateCatalogQuickPick();
      renderKitItemRows();
      document.getElementById('look-modal').style.display = 'flex';
    }

    function closeLookModal() {
      const m = document.getElementById('look-modal');
      if (m) m.style.display = 'none';
    }

    function handleLookFileSelected(input) {
      if (!input.files || !input.files[0]) return;
      const file = input.files[0];
      const reader = new FileReader();
      reader.onload = function(e) {
        const base64Data = e.target.result;
        const prev = document.getElementById('look-preview-img');
        const ph = document.getElementById('look-preview-placeholder');
        const st = document.getElementById('look-bg-status');
        prev.src = base64Data;
        prev.style.display = 'block';
        ph.style.display = 'none';
        st.innerText = 'Removing dummy background via Python AI (u2net)...';
        showToast('Removing dummy background cleanly...');

        window.__nexusPendingLookUpload = fetch('/api/upload', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ filename: file.name, image: base64Data, category: 'dummy', viewType: 'front' })
        }).then(r => r.json()).then(data => {
          if (data && data.url) {
            document.getElementById('look-form-img-url').value = data.url;
            prev.src = data.url.startsWith('/') ? data.url : '/' + data.url.replace(/^\.?\//, '');
            st.innerText = 'Background removed cleanly! Transparent runway cutout ready.';
            showToast('Dummy cutout ready!');
            autoCropKitFromDummy(true);
          } else {
            st.innerText = 'Upload failed — please retry.';
          }
        }).catch(err => {
          st.innerText = 'Background removal error: ' + err.message;
        }).finally(() => {
          window.__nexusPendingLookUpload = null;
        });
      };
      reader.readAsDataURL(file);
    }

    async function handleSaveLook() {
      const btn = document.getElementById('look-save-btn');
      if (window.__nexusPendingLookUpload) {
        showToast('Finalizing AI dummy background removal...');
        await window.__nexusPendingLookUpload;
      }
      if (pendingKitUploads > 0) {
        showToast('Waiting for outfit piece cutout upload...');
        await new Promise(r => setTimeout(r, 1200));
      }
      const editId = document.getElementById('look-edit-id').value.trim();
      const name = document.getElementById('look-form-name').value.trim();
      const subtitle = document.getElementById('look-form-subtitle').value.trim() || 'Custom Runway Dummy';
      const image = document.getElementById('look-form-img-url').value.trim();
      if (!name || !image) {
        showToast('Please enter a Dummy Name and upload a Dummy Photo!');
        return;
      }
      const kitItems = currentLookKitItems.filter(it => it && String(it.title || '').trim());

      if (btn) { btn.disabled = true; btn.innerText = 'Publishing...'; }
      try {
        const url = editId ? '/api/looks/' + encodeURIComponent(editId) : '/api/looks';
        const method = editId ? 'PUT' : 'POST';
        const res = await fetch(url, {
          method,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name, subtitle, image, kitItems })
        });
        const data = await res.json();
        if (!res.ok || data.error) throw new Error(data.error || 'Save failed');
        closeLookModal();
        await loadRunwayLooksAdmin();
        showToast(editId ? 'Runway dummy & outfit kit updated!' : 'New Runway Dummy & outfit kit published!');
      } catch (err) {
        showToast('Error saving dummy: ' + err.message);
      } finally {
        if (btn) { btn.disabled = false; btn.innerText = 'Save & Publish Dummy'; }
      }
    }

    async function deleteRunwayLook(lookId) {
      if (!confirm('Remove this Runway Dummy from Try the Look?')) return;
      try {
        const res = await fetch('/api/looks/' + encodeURIComponent(lookId), { method: 'DELETE' });
        if (res.ok) {
          await loadRunwayLooksAdmin();
          showToast('Runway dummy removed.');
        }
      } catch (err) {
        showToast('Delete error: ' + err.message);
      }
    }
